// n이 1과 자기 자신으로만 나누어떨어지면 1, 아니면 0을 돌려줘요.
int is_prime(int n) {
    int i;
    for (i = 1; i < n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}

int main(void) {
    int n = 13;
    printf("%d", is_prime(n));
    return 0;
}

